  ('02｜5F ライブラリ','本に囲まれて働く',['5階のライブラリは、本棚に囲まれた場所です。読む場所であり、働く場所でもあります。','ポップインは1日3,300円、11日分のパッケージが33,000円で、平日10時から18時に空いている席を使えます。会員になる前に、この階の空気を確かめる入口です。'],[(5,'5階のライブラリ'),(6,'5階のワークスペース')]),
  ('03｜2F エンゲージメントスペース','212㎡、着席80人・立食100人',['2階のエンゲージメントスペースは、コミュニティとのつながりを深めるための場所です。チームの会議、ミートアップ、日数を限ったオフサイトオフィス、交流会、組織のエンゲージメントを高める各種のプログラムに使われます。','広さは212.0㎡、着席で80人、立食で100人まで入ります。バーカウンター、冷蔵庫、プロジェクター、スクリーン、音響、Wi-Fi を備え、9時から22時まで、1日385,000円、1時間55,000円（6時間以上は1時間38,500円、いずれも税込）で借りられます。'],[(7,'2階のエンゲージメントスペース'),(8,'バーカウンターのあるエンゲージメントスペース')]),
  ('04｜建物全体','地下1階から6階まで、フロアごとの役目',['6階はプライベートルーム、5階はワークスペースと会議室、キッチン、ラウンジ、ベッドとライブラリ、4階はラウンジとプライベートルーム、3階はプライベートルーム、2階はエンゲージメントスペースとプライベートルーム、1階はカフェとプライベートルーム、駐輪場、地下1階はプライベートルームです。屋上には庭とテラスがあります。','永田町駅から2分、赤坂見附駅と麹町駅からそれぞれ8分です。'],[]),
