 facts=[('施設','BIRTH WORK 麻布十番'),('場所','東京都港区麻布十番2-20-7 麻布十番髙木ビル5F/8F/9F'),('構成','5F「集中」のフロア／8F・9F「憩い」のフロア'),('営業','年中無休（ビル点検等を除く）、24時間入退出可能'),('運営','株式会社髙木ビル')],
