 card='1階はコーヒーの香る時間制のワーキングカフェ',
 title='BASE POINT｜新宿駅10分、1階のワーキングカフェから3階のシェアオフィスまで3層のワークスペース',
 lead='新宿駅から歩いて10分、西新宿7丁目に BASE POINT（ベースポイント）はあります。1階は厳選したコーヒーを楽しみながら働ける時間制のワーキングカフェ、2階は会議室、3階はシェアオフィスです。全日7時から23時まで開いています。公式サイトに書かれている内容をもとに、この場所の要点をご案内します。',
